"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}


def _round_to_minor_unit(amount: Decimal, code: str) -> Decimal:
    exponent = Decimal(1).scaleb(-MINOR_UNITS.get(code, 2))
    return amount.quantize(exponent, rounding=ROUND_HALF_UP)


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    if source not in table.rates:
        raise RateError(f"no rate published for {source}")
    if target not in table.rates:
        raise RateError(f"no rate published for {target}")
    value = amount * table.rates[target] / table.rates[source]
    return _round_to_minor_unit(value, target)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    return f"{_round_to_minor_unit(amount, code):,f} {code}"

"""Reference rates published by the treasury rate service."""

import json
import re
import urllib.parse
import urllib.request
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from http.client import HTTPException

RATES_URL = "https://fx.treasury.internal/v1/rates"

_CODE = re.compile(r"[A-Z]{3}")


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def _check_code(code: object) -> str:
    if not isinstance(code, str) or not _CODE.fullmatch(code):
        raise RateError(f"invalid currency code: {code!r}")
    return code


def _check_rate(code: str, value: object) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (str, int, float)):
        raise RateError(f"rate for {code} is not a decimal: {value!r}")
    try:
        rate = Decimal(value if isinstance(value, str) else str(value))
    except InvalidOperation:
        raise RateError(f"rate for {code} is not a decimal: {value!r}") from None
    if not rate.is_finite() or rate <= 0:
        raise RateError(f"rate for {code} is not positive and finite: {value!r}")
    return rate


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        payload = json.loads(text)
    except ValueError as exc:
        raise RateError(f"response is not valid JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise RateError("payload is not a JSON object")
    for key in ("base", "as_of", "rates"):
        if key not in payload:
            raise RateError(f"payload is missing {key!r}")
    base = _check_code(payload["base"])
    as_of = payload["as_of"]
    if not isinstance(as_of, str):
        raise RateError(f"'as_of' is not a string: {as_of!r}")
    published = payload["rates"]
    if not isinstance(published, dict):
        raise RateError(f"'rates' is not an object: {published!r}")
    rates: dict[str, Decimal] = {}
    for code, value in published.items():
        if code == base:
            continue
        rates[_check_code(code)] = _check_rate(code, value)
    rates[base] = Decimal(1)
    return RateTable(base, as_of, rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    _check_code(base)
    url = f"{RATES_URL}?{urllib.parse.urlencode({'base': base})}"
    request = urllib.request.Request(url)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            if response.status != 200:
                raise RateError(f"rate service unavailable: HTTP {response.status}")
            body = response.read()
    except (OSError, HTTPException) as exc:
        raise RateError(f"rate service unavailable: {exc}") from exc
    return parse_rates(body.decode("utf-8"))
